    x = tau[((beta[x] >> l) | 1) << l];
  }

  if (j != beta[y]) {
    int l = lam[alfa[y] & ((1 << h) - 1)];
    y = tau[((beta[y] >> l) | 1) << l];
  }

  // Find z
  int z = (pi[x] <= pi[y]) ? x : y;
  return z;
}

